{
  "rules": [
    "If sentiment is positive (≥0.33) in recent history, model tends to overestimate prices; reduce forecast by 1–3% for next period.",
    "Model consistently overpredicts early in the 30-day horizon, especially after price spikes; apply downward correction of 2–5% for first 5–7 days.",
    "After a sharp price spike (e.g., >10% from prior peak), model often overshoots and fails to correct; cap forecast at 10% above prior peak for next 3–5 days.",
    "When sentiment is neutral or negative (≤0.20), model underestimates downward trends; add 1–3% to forecast to account for mean reversion or hidden demand.",
    "Model exhibits strong mean reversion bias: if 30-day forecast is >95% of prior 30-day average, reduce by 2–4% to avoid overfitting.",
    "If sentiment history shows repeated positive spikes (e.g., 3+ consecutive 0.33), model may be overconfident; apply 5–7% downward adjustment to prevent overcorrection."
  ]
}
